@router.get("/healthz", response_model=HealthResponse)
async def healthz(
    db: Annotated[AsyncSession, Depends(get_db_session)],
) -> HealthResponse:
    """Liveness probe — runs `SELECT 1` against the DB.

    Always returns 200; the response body indicates db health (OQ-P-02).
