68	export async function request<T>(
69	  method: HttpMethod,
70	  path: string,
71	  body?: unknown,
72	): Promise<T> {
73	  const url = joinUrl(API_BASE, path);
74	  const init: RequestInit = {
75	    method,
76	    headers: {
77	      Accept: "application/json, application/problem+json",
78	      ...(body !== undefined ? { "Content-Type": "application/json" } : {}),
79	    },
80	    body: body !== undefined ? JSON.stringify(body) : undefined,
81	  };
82	
83	  const resp = await fetch(url, init);
84	
85	  if (resp.status === 204) {
86	    // BR-C-08: DELETE returns no content.
87	    return undefined as unknown as T;
88	  }
89	
90	  if (!resp.ok) {
91	    const problem = await readProblem(resp);
92	    throw new ApiError(problem);
93	  }
94	
95	  // 2xx with body — assume JSON.
96	  return (await resp.json()) as T;
97	}
