20	export interface ProblemDetailParsed {
21	  status: number;
22	  title: string;
23	  detail?: string;
24	  instance?: string;
25	  errors: ProblemFieldError[];
26	}
27	
28	// Type guard for the raw envelope coming off the wire.
29	interface RawProblem {
30	  type?: string;
31	  title?: string;
32	  status?: number;
33	  detail?: string;
34	  instance?: string;
35	  errors?: Array<{
36	    loc?: Array<string | number>;
37	    msg?: string;
38	    type?: string;
39	  }>;
40	}
41	
42	function isObject(value: unknown): value is Record<string, unknown> {
43	  return typeof value === "object" && value !== null;
44	}
45	
46	export function parseProblemDetail(
47	  body: unknown,
48	  statusFallback: number,
49	): ProblemDetailParsed {
50	  if (!isObject(body)) {
51	    return {
52	      status: statusFallback,
53	      title: "Error",
54	      detail: undefined,
55	      errors: [],
56	    };
57	  }
58	
59	  const raw = body as RawProblem;
60	  const errors: ProblemFieldError[] = (raw.errors ?? [])
61	    .map((err) => {
62	      const locArr = err.loc ?? [];
63	      // Pydantic returns ["body", "<field>"] — drop the leading "body".
64	      const leaf =
65	        locArr.length > 0 ? String(locArr[locArr.length - 1]) : "_root";
66	      return {
67	        field: leaf,
68	        message: err.msg ?? "Invalid value",
69	        type: err.type ?? "value_error",
70	      };
71	    });
72	
73	  return {
74	    status: typeof raw.status === "number" ? raw.status : statusFallback,
75	    title: raw.title ?? "Error",
76	    detail: raw.detail,
77	    instance: raw.instance,
78	    errors,
